# Function to generate legal chess moves
def generate_moves(initial_board, moves_list):
    # Create a chess board from the initial moves
    board = chess.Board()
    for move in initial_moves:
        board.push(chess.Move.from_uci(move))

    # Get a list of all legal moves from the current board
    legal_moves = list(board.legal_moves)

    moves_set = set()
    for legal_move in legal_moves:
        moves_set.add(legal_move.uci())

    return list(legal_moves)

def main():
